package com.kaymlyn.planeteater.claude;

import com.kaymlyn.planeteater.simulation.celestial.CelestialBodyFactory;
import com.kaymlyn.planeteater.simulation.celestial.Star;
import com.kaymlyn.planeteater.simulation.physics.ManeuverDetails;
import com.kaymlyn.planeteater.simulation.physics.PhysicsConstants;
import com.kaymlyn.planeteater.simulation.physics.Vector3D;

/**
 * Test to verify the coast creation and propagation logic
 *
 * Generated by Claude (Sonnet 4.5)
 */
public class CoastCreationTest {

    public static void main(String[] args) {
        testCoastCreation();
    }

    public static void testCoastCreation() {
        System.out.println();
        System.out.println("COAST CREATION TEST");
        System.out.println();

        // Create a sun
        Star sun = CelestialBodyFactory.createMainSequenceStar("TestSun", 1.0);

        // Create an initial state at 1 AU
        Vector3D pos1 = new Vector3D(PhysicsConstants.AU, 0, 0);
        double orbitalVel = Math.sqrt(sun.getGravitationalParameter() / PhysicsConstants.AU);
        Vector3D vel1 = new Vector3D(0, orbitalVel, 0);

        System.out.println("Initial State:");
        System.out.printf("  Position: %s\n", formatVector(pos1));
        System.out.printf("  Velocity: %s\n", formatVector(vel1));
        System.out.println();

        // Create a maneuver at T=0
        ManeuverDetails initial = ManeuverDetails.createInitial(
                "Initial",
                pos1,
                vel1,
                sun,
                0.0
        );

        System.out.println("After createInitial:");
        System.out.printf("  Start Position: %s\n", formatVector(initial.getStartingPosition()));
        System.out.printf("  End Position: %s\n", formatVector(initial.getEndingPosition()));
        System.out.printf("  Start Time: %.2f s\n", initial.getStartTime());
        System.out.printf("  End Time: %.2f s\n", initial.getEndTime());
        System.out.println();

        // Simulate a burn that changes velocity
        Vector3D newVel = new Vector3D(0, orbitalVel + 5000, 0);  // Add 5 km/s
        ManeuverDetails burn = initial.thenBurn(newVel, "Test Burn");

        System.out.println("After burn:");
        System.out.printf("  Start Position: %s\n", formatVector(burn.getStartingPosition()));
        System.out.printf("  End Position: %s\n", formatVector(burn.getEndingPosition()));
        System.out.printf("  End Velocity: %s\n", formatVector(burn.getEndingVelocity()));
        System.out.printf("  ΔV: %.2f m/s\n", burn.getDeltaV());
        System.out.printf("  Start Time: %.2f s\n", burn.getStartTime());
        System.out.printf("  End Time: %.2f s\n", burn.getEndTime());
        System.out.println();

        // Now create a coast
        double coastTime = 86400.0;  // 1 day
        ManeuverDetails coast = burn.thenCoast(coastTime);

        System.out.println("After thenCoast:");
        System.out.printf("  Coast Duration: %.2f s (%.2f days)\n", coastTime, coastTime / 86400.0);
        System.out.printf("  Start Position: %s\n", formatVector(coast.getStartingPosition()));
        System.out.printf("  End Position: %s\n", formatVector(coast.getEndingPosition()));
        System.out.printf("  Start Time: %.2f s\n", coast.getStartTime());
        System.out.printf("  End Time: %.2f s\n", coast.getEndTime());
        System.out.println();

        // Key diagnostic: Does coast start where burn ended?
        Vector3D startDiff = coast.getStartingPosition().subtract(burn.getEndingPosition());
        double startDistance = startDiff.magnitude();

        System.out.println("CRITICAL CHECK: Coast Continuity");
        System.out.printf("  Burn End Position: %s\n", formatVector(burn.getEndingPosition()));
        System.out.printf("  Coast Start Position: %s\n", formatVector(coast.getStartingPosition()));
        System.out.printf("  Difference: %.2e m\n", startDistance);

        if (startDistance < 1.0) {
            System.out.println("  ✓ PASS: Coast starts where burn ended");
        } else {
            System.out.println("  ✗ FAIL: Coast starts at different position!");
        }
        System.out.println();

        // Now simulate telemetry generation for the coast
        System.out.println("Simulating Telemetry Generation:");
        System.out.println("─────────────────────────────────────────────────────");

        double timeStep = 3600.0;  // 1 hour
        int stepsToShow = 3;

        for (int step = 0; step < stepsToShow; step++) {
            double timeInCoast = step * timeStep;

            // This is what the FIXED code should do:
            double cumulativeTime = coast.getStartTime() + timeInCoast;

            System.out.printf("\nStep %d (t_coast = %.2f h):\n", step, timeInCoast / 3600.0);
            System.out.printf("  Cumulative Time: %.2f s\n", cumulativeTime);

        }

        System.out.println("\n");
    }

    private static String formatVector(Vector3D v) {
        return String.format("(%.6e, %.6e, %.6e)", v.getX(), v.getY(), v.getZ());
    }
}